    ['“మకాం” అర్థం?', 'నివాసం', 'ప్రయాణం', 'భోజనం', 'పని'],
    ['“కనుమరుగు” అర్థం?', 'కనబడకపోవడం', 'కనబడటం', 'వినపడటం', 'రావడం'],
    ['“బసవన్న” పర్యాయపదం?', 'వృషభం', 'ధేనువు', 'గోవు', 'పాదపం'],
    ['“తిలోదకాలివ్వడం” అర్థం?', 'సంబంధం తెంచుకోవడం', 'నీరు పోయడం', 'పూజ చేయడం', 'దానం చేయడం'],
