SEC = [
 (58, 'చిత్రం – ప్రశ్నలు', [
  '1. ఈ సన్నివేశాలు (గంగిరెద్దులు, హరిదాసు, రంగవల్లులు) సంక్రాంతి పండుగ రోజుల్లో కనిపిస్తాయి.',
  '2. సంక్రాంతి (ధనుర్మాసం) రోజుల్లో హరిదాసు ఇంటికి వస్తాడు.',
  '3. గంగిరెద్దుల వాళ్ళు, హరిదాసులు, బుడబుక్కల వాళ్ళు, కొమ్మదాసరులు, జంగమదేవరలు కనిపిస్తారు; ఇళ్ళ ముందు రంగవల్లులు, గొబ్బెమ్మలు ఉంటాయి.']),
 (61, 'అవగాహన – ప్రతిస్పందన', [
  '1. నేను చూసిన కళారూపం – బుర్రకథ: ముగ్గురు కళాకారులు; ప్రధాన కథకుడు తంబుర మీటుతూ కథ చెబుతాడు, ఇద్దరు వంతలు బుర్రలు (డక్కీలు) వాయిస్తూ “తందాన తాన” అంటూ హాస్యం, రాజకీయ విషయాలు చెబుతారు. (హరికథ, తోలుబొమ్మలాట, కోలాటం కూడా రాయవచ్చు.)',
  '2. నాగరికతతో పాటు అందమైన జానపద కళ గంగిరెద్దాట కనుమరుగవుతోంది; కళాకారులకు ఆదరణ, ఆదాయం తగ్గి కూలిపనులకు వెళ్ళాల్సి వస్తోంది – అందుకే రచయితకు బాధ కలిగింది.',
  '3. బసవయ్య చిన్నప్పటి నుండి తండ్రితో ఊరూరా తిరిగాడు; తండ్రి మాటలు, పద్ధతులు గమనించాడు; తండ్రి మోళీలు చేయిస్తుంటే రాండోలు వాయించాడు – అలా ఆట మెలకువలన్నీ నేర్చుకున్నాడు.',
  '4. పేరా: 1) అ) సమాజ వినోదం కోసం 2) ఆ) స్థలపురాణాలు 3) ఇ) ఎరుక చెప్పే సోదె 4) ప్రశ్న: “కురవంజి ఏ ప్రాంతం నుండి పుట్టింది?” / “కురవలు ఎవరు?”']),
 (62, 'వ్యక్తీకరణ – సృజనాత్మకత; పదజాలం', [
  'అ)1. 1) గంగిరెద్దుల వారికి సొంత ఊరు, భూమి, స్థిరమైన ఇల్లు లేవు. 2) ఊరూరా తిరుగుతూ ఆట చూపి వచ్చిన దానితో బతుకుతారు. 3) ఏ ఊరిలో పంటలు బాగా పండుతాయో, దానం చేసే మంచి మనుషులుంటారో అక్కడ వారికి బతుకు గడుస్తుంది. 4) అందుకే “ధర్మ ప్రభువులుంటే అదే నా ఊరు” అన్నాడు.',
  'అ)2. 1) పరమేశ్వరుడే నందిని ఆడించాడని చెబుతారు. 2) మహాచక్రవర్తులు, రాజుల కాలంలో ఈ ఆట గొప్పగా ఉండేది. 3) పాత చిత్రాల్లో రాకుమారులు, రాజకుమార్తెలు గంగిరెద్దులాట చూసే ఘట్టాలు ఉన్నాయి. 4) తరతరాలుగా కుటుంబ వృత్తిగా వస్తోంది – కాబట్టి ఇది ప్రాచీనమైనది.',
  'అ)3. 1) రాండోలు – రెండు చేతులతో రెండు పుల్లలు పట్టుకుని ఒక పుడకతో చర్మంపై, మరోవైపు వరుసలు వాయిస్తారు. 2) సన్నాయి – ఊదుతూ రాగం వాయిస్తారు. 3) శ్రుతి – సన్నాయికి శ్రుతి పోస్తారు. 4) ఈ వాయిద్యాల లయకు అనుగుణంగా ఎద్దు మోళీలు చేస్తుంది.',
  'అ)4. 1) డా. రావూరి భరద్వాజ 1927లో గుంటూరు జిల్లా తాడికొండలో జన్మించారు. 2) తొలి కథ “విమల”. 3) 37 కథాసంపుటాలు, 43 పిల్లల కథలు, 17 నవలలు రాశారు. 4) “పాకుడు రాళ్లు” నవలకు జ్ఞానపీఠ పురస్కారం పొందారు. 5) కేంద్ర సాహిత్య అకాడమీ, గోపీచంద్ జాతీయ పురస్కారాలు కూడా పొందారు.',
  'ఆ)1. 1) గంగిరెద్దులాటకు పల్లెటూళ్ళలోనే ఆదరణ ఉంది. 2) పట్టణాల్లో రోడ్ల రద్దీ, ఆట వేయడానికి ఖాళీ స్థలం (గడి) దొరకదు. 3) పట్టణ ప్రజలు TV, సినిమాల వైపు మళ్ళారు. 4) పల్లెల్లో రైతులు ధాన్యం, బట్టలు, ఎద్దుకు దాణా ఇస్తారు. 5) గంగిరెద్దులు ఎద్దులే కాబట్టి మేత, నీరు పల్లెల్లోనే సులభం. 6) సంక్రాంతి వంటి పండుగల సంప్రదాయం పల్లెల్లోనే బతికి ఉంది. 7) బసవయ్య “మారుమూల పల్లెటూళ్ళను పట్టుకుని వేళ్ళాడుతున్నాం” అన్నాడు. 8) పల్లె ప్రజలే వీరిని ఆదరించే ధర్మ ప్రభువులు.',
  'ఆ)2. బుర్రకథ (నమూనా): 1) బుర్రకథ తెలుగు ప్రజల ప్రసిద్ధ జానపద కళారూపం. 2) ముగ్గురు కళాకారులు ఉంటారు. 3) కథకుడు తంబుర మీటుతూ, కాళ్ళకు గజ్జెలతో నృత్యం చేస్తూ కథ చెబుతాడు. 4) ఇరువైపులా వంతలు బుర్రలు వాయిస్తారు. 5) “తందాన తాన” అనే పల్లవి అందరినీ ఆకట్టుకుంటుంది. 6) అల్లూరి సీతారామరాజు, బొబ్బిలి యుద్ధం వంటి వీరగాథలు చెబుతారు. 7) హాస్యం, సామాజిక సందేశం కలిసి ఉంటాయి. 8) షేక్ నాజర్ వంటి కళాకారులు దీనికి కీర్తి తెచ్చారు. 9) ఈ కళ అంతరించకుండా బడుల్లో, పండుగల్లో ప్రదర్శించాలి.',
  'పదజాలం అ) 1. ఆప్యాయం = ప్రేమ – అమ్మమ్మ ఆప్యాయంగా అన్నం పెట్టింది. 2. అనుగుణం = తగినట్లు – పాటకు అనుగుణంగా నృత్యం చేశారు. 3. కనుమరుగు = ఇ) కనబడకపోవడం.',
  'ఆ) 1. నాన్న = తండ్రి, జనకుడు. 2. బసవన్న = వృషభం, ఎద్దు.']),
 (63, 'పదజాలం ఆ)3, ఈ)', [
  'ఆ) 3. సంతోషం = ఆనందం, సంతసం.',
  'ఈ) 1. పట్టుకొని వేలాడు – మా తాత పాత ఇంటినే పట్టుకొని వేలాడుతున్నారు. 2. కాలుదువ్వు – చిన్న విషయానికే వాళ్ళు కాలుదువ్వుతున్నారు. 3. తిలోదకాలివ్వడం – చెడు అలవాట్లకు తిలోదకాలివ్వాలి.']),
 (64, 'వచనం – అభ్యాసం 1, 2', [
  'అభ్యాసం 1: నిత్య ఏకవచనాలు – నెయ్యి, బంగారము, నూనె, ఇనుము. నిత్య బహువచనాలు – పాలు, కందులు, ఆవాలు, మినుములు.',
  'అభ్యాసం 2: 1. మా పొలంలో ఈ ఏడాది వరి బాగా పండింది.']),
 (65, 'అభ్యాసం 2, 3; చమత్కార పద్యం', [
  '2. షాపు నుండి పెసలు తీసుకురా (“పెస” కాదు). 3. దీపంలో వేయడానికి నూనె లేదు.',
  'అభ్యాసం 3: వంటగదిలో నిత్య ఏకవచనాలు – ఉప్పు, పసుపు, నెయ్యి, నూనె, బియ్యం, ఇంగువ, మజ్జిగ; నిత్య బహువచనాలు – పాలు, పెసలు, కందులు, మినుములు, ఆవాలు, శనగలు.',
  'చమత్కార పద్యం: “కప్పను చూసి పాము వణికింది” అనే సమస్యకు – చివరి పాదంలో “వెం” + “కప్ప” = వెంకప్ప; చెప్పులు, కర్రతో కాపలాకు వస్తున్న వెంకప్పను చూసి పాము గడగడ వణికింది అని కవి పూరించాడు.']),
 (66, 'చదవండి – ఆనందించండి: గురి', [
  'సారాంశం: 1) విదర్భ రాజు విక్రమసేనుడు వేటలో లేడిపిల్లపై బాణం వేయగా అది చెట్టుకు తగిలింది. 2) సైనికాధికారి అలవాటుగా “భలే గురి” అనగా రాజు కోపించాడు. 3) మంత్రి రాంభట్టు “మహారాజు అమాయక జంతువులను వేటాడరు, లేడిని పారిపొమ్మని గురి తప్పకుండా చెట్టుకు కొట్టారు” అని చెప్పాడు. 4) రాజు సంతోషించాడు, సైనికుడు బతికాడు. నీతి: సమయస్ఫూర్తితో ఆపదను తప్పించవచ్చు.'])]
